CREATE TABLE IF NOT EXISTS disc_extras (
    id SERIAL PRIMARY KEY,
    disc_id INT NOT NULL REFERENCES discs(id) ON DELETE CASCADE,
    file_type VARCHAR(16) NOT NULL,
    size BIGINT NOT NULL,
    crc32 VARCHAR(8) NOT NULL,
    md5 VARCHAR(32) NOT NULL,
    sha1 VARCHAR(40) NOT NULL
);

CREATE TEMP TABLE IF NOT EXISTS xgd_extras_import (
    disc_id INT NOT NULL,
    file_type VARCHAR(16) NOT NULL,
    crc32 VARCHAR(8) NOT NULL,
    md5 VARCHAR(32) NOT NULL,
    sha1 VARCHAR(40) NOT NULL
);





















-- Import only the hashes that are in redump comments
SELECT i.disc_id, i.file_type, 2048, i.crc32, i.md5, i.sha1
FROM xgd_extras_import i
JOIN discs d ON d.id = i.disc_id
WHERE d.media_type_code = 'xgd'
  AND d.comments ~* ('(^|[^0-9a-f])' || i.crc32 || '($|[^0-9a-f])');

CREATE INDEX IF NOT EXISTS disc_extras_disc_id_idx ON disc_extras (disc_id);

UPDATE systems
SET archives_dirty = TRUE
WHERE 'xgd' = ANY(media_types);


-- Remove imported CRC32 hashes from comments
DO $$
DECLARE
    r RECORD;
    v_labels CONSTANT TEXT[] := ARRAY[
        'DMI',
        'PFI',
        'SS(?:v[12])?'
    ];
    v_crcs TEXT[];
    v_old TEXT;
    v_new TEXT;
    v_lines TEXT[];
    v_out TEXT[];
    v_line TEXT;
    v_m TEXT[];
    v_total INT;
    v_kept TEXT[];
    i INT;
BEGIN
    FOR r IN
        SELECT d.id AS disc_id,
               d.comments,
               array_agg(e.crc32::TEXT) FILTER (WHERE e.file_type = 'dmi') AS dmi,
               array_agg(e.crc32::TEXT) FILTER (WHERE e.file_type = 'pfi') AS pfi,
               array_agg(e.crc32::TEXT) FILTER (WHERE e.file_type = 'ss')  AS ss
        FROM discs d
        JOIN disc_extras e ON e.disc_id = d.id
        WHERE d.comments IS NOT NULL
          AND EXISTS (
            SELECT 1
            FROM xgd_extras_import i
            WHERE i.disc_id = e.disc_id
              AND i.file_type = e.file_type
              AND i.crc32 = e.crc32
        )
        GROUP BY d.id
    LOOP
        v_old := r.comments;
        v_lines := regexp_split_to_array(v_old, '\n');
        v_out := '{}';
        FOREACH v_line IN ARRAY v_lines LOOP
            FOR i IN 1..3 LOOP
                v_m := regexp_match(
                    v_line,
                    format(
                        '^((?:<b>%1$s(?![A-Za-z0-9]):?</b>:? *|%1$s(?![A-Za-z0-9]):? *))([0-9A-Fa-f]{8}(?:(?: *, *| +)[0-9A-Fa-f]{8})*)( *)$',
                        v_labels[i]
                    ),
                    'i'
                );
                CONTINUE WHEN v_m IS NULL;

                v_crcs := CASE i WHEN 1 THEN r.dmi WHEN 2 THEN r.pfi ELSE r.ss END;
                EXIT WHEN v_crcs IS NULL;

                SELECT count(*) INTO v_total FROM regexp_matches(v_m[2], '[0-9A-Fa-f]{8}', 'g');
                v_kept := ARRAY(
                    SELECT t[1] FROM regexp_matches(v_m[2], '[0-9A-Fa-f]{8}', 'g') AS t
                    WHERE lower(t[1]) <> ALL (v_crcs)
                );

                IF COALESCE(cardinality(v_kept), 0) = 0 THEN
                    v_line := NULL;
                ELSIF cardinality(v_kept) < v_total THEN
                    v_line := v_m[1] || array_to_string(v_kept, ', ') || v_m[3];
                END IF;
                EXIT;
            END LOOP;

            IF v_line IS NOT NULL THEN
                v_out := v_out || v_line;
            END IF;
        END LOOP;

        v_new := array_to_string(v_out, E'\n');

        IF v_new IS DISTINCT FROM v_old THEN
            v_new := NULLIF(btrim(regexp_replace(v_new, '(\n[ ]*){3,}', E'\n\n', 'g'), E' \n'), '');
            UPDATE discs SET comments = v_new WHERE id = r.disc_id;
        END IF;
    END LOOP;
END
$$;

DROP TABLE xgd_extras_import;
